//! The limits of each engine a map can reach (ENGT-5): each BSP lump's count, a face's extent,
//! edicts, the model and sound precaches and light styles. id's are BSP-16's compiler limits
//! and LIMIT-6's server limits; QuakeSpasm's, Ironwail's, vkQuake's, FTEQW's and DarkPlaces'
//! are generated by `cargo xtask engines` from their pinned sources (`tables.rs`); the KEX
//! rerelease has no source, so its limits are unknown.

use qc_progs::limits::{
    LIMIT_MAX_EDICTS, LIMIT_MAX_LIGHTSTYLES, LIMIT_MAX_MODELS, LIMIT_MAX_SOUNDS,
};
use qs_bsp::limits::{
    BSP_MAX_MAP_CLIPNODES, BSP_MAX_MAP_EDGES, BSP_MAX_MAP_ENTITIES, BSP_MAX_MAP_ENTSTRING,
    BSP_MAX_MAP_FACES, BSP_MAX_MAP_LIGHTING, BSP_MAX_MAP_MARKSURFACES, BSP_MAX_MAP_MODELS,
    BSP_MAX_MAP_NODES, BSP_MAX_MAP_PLANES, BSP_MAX_MAP_SURFEDGES, BSP_MAX_MAP_TEXINFO,
    BSP_MAX_MAP_TEXTURES, BSP_MAX_MAP_VERTS, BSP_MAX_MAP_VISIBILITY,
};
use qs_bsp::{BSP_MAX_MAP_LEAFS, BSP_MAX_SURFACE_EXTENT};

use std::sync::LazyLock;

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use crate::{Engine, tables};

/// A limit of an engine that a map can reach (ENGT-5.4).
#[derive(
    Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize, JsonSchema,
)]
#[serde(rename_all = "snake_case")]
pub enum MapLimit {
    /// The models lump: the world and each brush entity's model.
    Models,
    /// The entities of the entity lump.
    Entities,
    /// The entity lump's text, in bytes.
    EntityText,
    /// The planes lump.
    Planes,
    /// The nodes lump.
    Nodes,
    /// The clipnodes lump.
    Clipnodes,
    /// The leafs lump.
    Leafs,
    /// The world model's `visleafs`, the leaves a visibility row covers.
    Visleafs,
    /// The vertexes lump.
    Vertexes,
    /// The faces lump.
    Faces,
    /// The marksurfaces lump.
    Marksurfaces,
    /// The texinfo lump.
    Texinfo,
    /// The edges lump.
    Edges,
    /// The surfedges lump.
    Surfedges,
    /// The textures of the textures lump.
    Textures,
    /// The lighting lump, in bytes.
    Lighting,
    /// The visibility lump, in bytes.
    Visibility,
    /// The largest texture extent of a face that is not `TEX_SPECIAL`, in texels (BSP-9.4).
    FaceExtent,
    /// The edicts in use, the world and the client slots among them (LIMIT-6.1).
    Edicts,
    /// The models precached, the world among them (LIMIT-6.2).
    ModelPrecaches,
    /// The sounds precached (LIMIT-6.2).
    SoundPrecaches,
    /// The light styles the program sets, each numbered below the limit.
    LightStyles,
}

impl MapLimit {
    /// Every limit, the lumps in BSP-16's order, then the face extent and the server's.
    pub const ALL: [Self; 22] = [
        Self::Models,
        Self::Entities,
        Self::EntityText,
        Self::Planes,
        Self::Nodes,
        Self::Clipnodes,
        Self::Leafs,
        Self::Visleafs,
        Self::Vertexes,
        Self::Faces,
        Self::Marksurfaces,
        Self::Texinfo,
        Self::Edges,
        Self::Surfedges,
        Self::Textures,
        Self::Lighting,
        Self::Visibility,
        Self::FaceExtent,
        Self::Edicts,
        Self::ModelPrecaches,
        Self::SoundPrecaches,
        Self::LightStyles,
    ];

    /// Its name in words, such as `clipnodes`.
    #[must_use]
    pub const fn name(self) -> &'static str {
        match self {
            Self::Models => "models",
            Self::Entities => "entities",
            Self::EntityText => "bytes of entity text",
            Self::Planes => "planes",
            Self::Nodes => "nodes",
            Self::Clipnodes => "clipnodes",
            Self::Leafs => "leafs",
            Self::Visleafs => "visleafs",
            Self::Vertexes => "vertexes",
            Self::Faces => "faces",
            Self::Marksurfaces => "marksurfaces",
            Self::Texinfo => "texinfo",
            Self::Edges => "edges",
            Self::Surfedges => "surfedges",
            Self::Textures => "textures",
            Self::Lighting => "bytes of lighting",
            Self::Visibility => "bytes of visibility",
            Self::FaceExtent => "texels of face extent",
            Self::Edicts => "edicts",
            Self::ModelPrecaches => "precached models",
            Self::SoundPrecaches => "precached sounds",
            Self::LightStyles => "light styles",
        }
    }

    /// Whether a compile measures it, from the BSP (ENGT-5.4), rather than a spawn of the map.
    #[must_use]
    pub const fn measured_by(self) -> Measure {
        match self {
            Self::Edicts | Self::ModelPrecaches | Self::SoundPrecaches | Self::LightStyles => {
                Measure::Spawn
            }
            Self::Models
            | Self::Entities
            | Self::EntityText
            | Self::Planes
            | Self::Nodes
            | Self::Clipnodes
            | Self::Leafs
            | Self::Visleafs
            | Self::Vertexes
            | Self::Faces
            | Self::Marksurfaces
            | Self::Texinfo
            | Self::Edges
            | Self::Surfedges
            | Self::Textures
            | Self::Lighting
            | Self::Visibility
            | Self::FaceExtent => Measure::Compile,
        }
    }
}

/// Where a limit's use is measured (ENGT-5.4).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Measure {
    /// In the BSP a compile writes.
    Compile,
    /// In the map spawned by the game's own code.
    Spawn,
}

/// What an engine does with a map past a limit (ENGT-5.5).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum Past {
    /// It stops: the map does not load, or the game ends with an error.
    Refused,
    /// It loads the map and prints a warning, under `developer` for most.
    Warned,
    /// The engine checks nothing, but id's compiler cannot write the map (BSP-16.1).
    Tools,
    /// The engine checks nothing and writes past an array: what follows is undefined.
    Undefined,
}

/// The formats a limit's check reads (ENGT-5.5).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum Applies {
    /// Every format the engine reads.
    AllFormats,
    /// BSP29 only: the engine's loader of BSP29's 16-bit lumps.
    Bsp29,
}

/// The format a map is compiled to.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum MapFormat {
    /// id's BSP29.
    Bsp29,
    /// BSP2, whose lumps are 32-bit (BSP-17).
    Bsp2,
}

/// One limit of one engine, with where it is stated.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct LimitFact {
    /// The limit.
    pub limit: MapLimit,
    /// The most the engine takes.
    pub most: usize,
    /// What it does past that.
    pub past: Past,
    /// The formats the check reads.
    pub applies: Applies,
    /// The source it is read from: an id of `sources.toml`, or `id` for id's own.
    pub source: &'static str,
    /// The file.
    pub path: &'static str,
}

/// An engine's bound on a limit, for a map of one format (ENGT-5.7).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Bound {
    /// The engine takes at most this.
    At(LimitFact),
    /// The engine's pinned source checks nothing for this limit.
    Unlimited,
    /// The engine has no source, so its limit is not known.
    Unknown,
}

/// Whether an engine reads BSP2 (ENGT-5.6).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum Bsp2 {
    /// Its source loads BSP2.
    Reads,
    /// It reads BSP29 only (BSP-1.2).
    DoesNotRead,
    /// It has no source, so it is not known.
    Unknown,
}

/// `WinQuake/bspfile.h`, where id's compiler limits are (BSP-16).
const BSPFILE_H: &str = "WinQuake/bspfile.h";
/// `WinQuake/quakedef.h`, where id's server limits are (LIMIT-6).
const QUAKEDEF_H: &str = "WinQuake/quakedef.h";
/// `WinQuake/model.c`, whose `CalcSurfaceExtents` refuses a face's extent (BSP-9.4) and
/// whose `Mod_DecompressVis` row holds `MAX_MAP_LEAFS` leaves (BSP-6).
const MODEL_C: &str = "WinQuake/model.c";
/// The source of id's own limits, which are this project's statements of id's code.
const ID: &str = "id";

impl LimitFact {
    /// A limit of id's, from the constants of BSP-16 and LIMIT-6.
    const fn id(limit: MapLimit, most: usize, past: Past, path: &'static str) -> Self {
        Self {
            limit,
            most,
            past,
            applies: Applies::AllFormats,
            source: ID,
            path,
        }
    }
}

/// id's limits (ENGT-5.7): BSP-16's compiler limits, which id's engine does not check; its
/// visibility row of `MAX_MAP_LEAFS` leaves (BSP-6); BSP-9.4's face extent; and LIMIT-6's
/// edicts and precaches, a precache list's entry 0 being empty, and its 64 light styles,
/// which `PF_lightstyle` does not check (BUILTIN-12.6).
static VANILLA_LIMITS: LazyLock<[LimitFact; 22]> = LazyLock::new(|| {
    [
        LimitFact::id(MapLimit::Models, BSP_MAX_MAP_MODELS, Past::Tools, BSPFILE_H),
        LimitFact::id(
            MapLimit::Entities,
            BSP_MAX_MAP_ENTITIES,
            Past::Tools,
            BSPFILE_H,
        ),
        LimitFact::id(
            MapLimit::EntityText,
            BSP_MAX_MAP_ENTSTRING,
            Past::Tools,
            BSPFILE_H,
        ),
        LimitFact::id(MapLimit::Planes, BSP_MAX_MAP_PLANES, Past::Tools, BSPFILE_H),
        LimitFact::id(MapLimit::Nodes, BSP_MAX_MAP_NODES, Past::Tools, BSPFILE_H),
        LimitFact::id(
            MapLimit::Clipnodes,
            BSP_MAX_MAP_CLIPNODES,
            Past::Tools,
            BSPFILE_H,
        ),
        LimitFact::id(MapLimit::Leafs, BSP_MAX_MAP_LEAFS, Past::Tools, BSPFILE_H),
        LimitFact::id(
            MapLimit::Visleafs,
            BSP_MAX_MAP_LEAFS,
            Past::Undefined,
            MODEL_C,
        ),
        LimitFact::id(
            MapLimit::Vertexes,
            BSP_MAX_MAP_VERTS,
            Past::Tools,
            BSPFILE_H,
        ),
        LimitFact::id(MapLimit::Faces, BSP_MAX_MAP_FACES, Past::Tools, BSPFILE_H),
        LimitFact::id(
            MapLimit::Marksurfaces,
            BSP_MAX_MAP_MARKSURFACES,
            Past::Tools,
            BSPFILE_H,
        ),
        LimitFact::id(
            MapLimit::Texinfo,
            BSP_MAX_MAP_TEXINFO,
            Past::Tools,
            BSPFILE_H,
        ),
        LimitFact::id(MapLimit::Edges, BSP_MAX_MAP_EDGES, Past::Tools, BSPFILE_H),
        LimitFact::id(
            MapLimit::Surfedges,
            BSP_MAX_MAP_SURFEDGES,
            Past::Tools,
            BSPFILE_H,
        ),
        LimitFact::id(
            MapLimit::Textures,
            BSP_MAX_MAP_TEXTURES,
            Past::Tools,
            BSPFILE_H,
        ),
        LimitFact::id(
            MapLimit::Lighting,
            BSP_MAX_MAP_LIGHTING,
            Past::Tools,
            BSPFILE_H,
        ),
        LimitFact::id(
            MapLimit::Visibility,
            BSP_MAX_MAP_VISIBILITY,
            Past::Tools,
            BSPFILE_H,
        ),
        LimitFact::id(
            MapLimit::FaceExtent,
            usize::try_from(BSP_MAX_SURFACE_EXTENT).unwrap_or_default(),
            Past::Refused,
            MODEL_C,
        ),
        LimitFact::id(
            MapLimit::Edicts,
            LIMIT_MAX_EDICTS,
            Past::Refused,
            QUAKEDEF_H,
        ),
        LimitFact::id(
            MapLimit::ModelPrecaches,
            LIMIT_MAX_MODELS.saturating_sub(1),
            Past::Refused,
            QUAKEDEF_H,
        ),
        LimitFact::id(
            MapLimit::SoundPrecaches,
            LIMIT_MAX_SOUNDS.saturating_sub(1),
            Past::Refused,
            QUAKEDEF_H,
        ),
        LimitFact::id(
            MapLimit::LightStyles,
            LIMIT_MAX_LIGHTSTYLES,
            Past::Undefined,
            QUAKEDEF_H,
        ),
    ]
});

impl Engine {
    /// The limits its source states (ENGT-5.7): id's for Vanilla, the generated tables for
    /// the five engines with sources, none for KEX.
    #[must_use]
    pub fn limit_facts(self) -> &'static [LimitFact] {
        match self {
            Self::Vanilla => VANILLA_LIMITS.as_slice(),
            Self::QuakeSpasm => tables::QUAKESPASM_LIMITS,
            Self::Ironwail => tables::IRONWAIL_LIMITS,
            Self::VkQuake => tables::VKQUAKE_LIMITS,
            Self::Fteqw => tables::FTEQW_LIMITS,
            Self::DarkPlaces => tables::DARKPLACES_LIMITS,
            Self::Kex => &[],
        }
    }

    /// Its bound on `limit` for a map of `format` (ENGT-5.7): the least of the facts that read
    /// that format; [`Bound::Unlimited`] when its source states none; [`Bound::Unknown`] for
    /// KEX.
    #[must_use]
    pub fn bound(self, limit: MapLimit, format: MapFormat) -> Bound {
        if self == Self::Kex {
            return Bound::Unknown;
        }
        self.limit_facts()
            .iter()
            .filter(|fact| fact.limit == limit)
            .filter(|fact| match (fact.applies, format) {
                (Applies::AllFormats, _) | (Applies::Bsp29, MapFormat::Bsp29) => true,
                (Applies::Bsp29, MapFormat::Bsp2) => false,
            })
            .min_by_key(|fact| fact.most)
            .map_or(Bound::Unlimited, |fact| Bound::At(*fact))
    }

    /// Whether it reads BSP2 (ENGT-5.6).
    #[must_use]
    pub const fn bsp2(self) -> Bsp2 {
        match self {
            Self::Vanilla => Bsp2::DoesNotRead,
            Self::QuakeSpasm => tables::QUAKESPASM_BSP2,
            Self::Ironwail => tables::IRONWAIL_BSP2,
            Self::VkQuake => tables::VKQUAKE_BSP2,
            Self::Fteqw => tables::FTEQW_BSP2,
            Self::DarkPlaces => tables::DARKPLACES_BSP2,
            Self::Kex => Bsp2::Unknown,
        }
    }
}

